head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.checkVal = function() {
    var top = WebSquare.wUnit.getDomById($p.id+'wq_uuid_1_control').style.top;
    //if (WebSquare.text.BASE64Decode(WebSquare.ver).indexOf("5.0_4") > -1) {
        return top == '172px';
    //} else {
    //    return top == '170px';
    //}
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'wq_uuid_1_btn_scrollRight').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'wq_uuid_1_tab_tabs8_tabHTML').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'wq_uuid_1_tab_tabs8')).hasClass('w2tabcontrol_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
